import torch
from vllm.config import VllmConfig


class _RMSNormBiasWrapper:
    """Wrapper for npu_add_rms_norm_bias op used in sequence parallelism."""

    def __init__(self, eps: float = 1e-6):
        self.eps = eps

    def __call__(self, input, residual, weight):
        """Call the norm op with the same arity Dynamo emits for its defaults."""
        if self.eps == 1e-6:  # 特判 eps==1e-6 时省略 eps 参数
            return torch.ops._C_ascend.npu_add_rms_norm_bias(input, residual, weight)
        return torch.ops._C_ascend.npu_add_rms_norm_bias(input, residual, weight, None, self.eps)


def _get_norm_wrapper(config: VllmConfig):
    """Get the appropriate norm wrapper for sequence parallelism."""
    eps = config.model_config.get_norm_eps()
    return _RMSNormBiasWrapper(eps=eps)

